#!/usr/bin/env node
// Writes tests/fixtures/quran-first-verses.json: the provider's verbatim text of the first
// verse of every surah. Used to test that Bismillah handling is lossless on real data.
// Quran text: Tanzil Project (https://tanzil.net), CC BY 3.0, verbatim copy — do not edit.
import { writeFile, mkdir } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const API_BASE = process.env.VITE_QURAN_API_BASE ?? 'https://api.alquran.cloud/v1';
const OUT = resolve(dirname(fileURLToPath(import.meta.url)), '../tests/fixtures/quran-first-verses.json');

const res = await fetch(`${API_BASE}/quran/quran-uthmani`);
if (!res.ok) throw new Error(`Provider responded ${res.status}`);
const { data } = await res.json();
if (data?.surahs?.length !== 114) throw new Error('Unexpected provider response');

const output = {
  provenance: {
    provider: 'alquran-cloud',
    edition: data.edition?.identifier,
    textSource: 'Tanzil Project — https://tanzil.net (CC BY 3.0). Verbatim; changing it is not allowed.',
    fetchedAt: new Date().toISOString(),
    note: 'Generated by scripts/fetch-quran-fixtures.mjs. Do not edit by hand.',
  },
  firstVerses: data.surahs.map((s) => ({ surah: s.number, text: s.ayahs[0].text })),
};

await mkdir(dirname(OUT), { recursive: true });
await writeFile(OUT, JSON.stringify(output, null, 2) + '\n');
console.log(`Wrote first verses of ${output.firstVerses.length} surahs to ${OUT}`);
